{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Restful group immersion</title>
  <meta name="description" content="A modern sound immersion designed for clarity and calm. Local gatherings, private sessions, and micro-practices to anchor your day.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <h1 class="logo">{{BUSINESS_NAME}}</h1>
      <p class="tag">{{TAGLINE}}</p>
    </div>
    <nav class="main-nav">
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Learn</a>
      <a href="faq.html">Questions</a>
      <a href="book.html" class="cta-link">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="hero" id="hero">
      <svg class="hero-pattern" viewBox="0 0 400 80" preserveAspectRatio="none" aria-hidden>
        <defs>
          <pattern id="p" patternUnits="userSpaceOnUse" width="40" height="40">
            <rect width="40" height="40" fill="#0a0a0a" opacity="0.02"></rect>
            <circle cx="8" cy="8" r="3" fill="#0a0a0a" opacity="0.06" />
            <circle cx="32" cy="32" r="2" fill="#0a0a0a" opacity="0.04" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#p)"></rect>
      </svg>
      <div class="hero-inner">
        <h2>Quiet calibration for busy minds</h2>
        <p class="lead">A guided, communal experience to soften stress and sharpen presence across your week.</p>
        <div class="hero-ctas">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <button class="btn ghost" id="tryNowBtn">Try a short practice</button>
        </div>
      </div>
    </section>

    <section class="diagnostic" id="diagnostic">
      <h3>Who should pause — and when to check in</h3>
      <p>Our gatherings are gentle but deep. Please consult with a healthcare professional before attending if you are pregnant, have uncontrolled epilepsy, recent head injury, severe psychiatric conditions, or implantable electronic devices. If you take medication that affects consciousness, speak with your clinician.</p>
      <p class="small">Contraindications are taken seriously; reach us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> for private guidance.</p>
    </section>

    <section class="plan" id="programs">
      <h3>Programs — shaped for modern attention</h3>
      <div class="plans-grid">
        <article class="plan-card">
          <h4>Resonance Drop — 45 minutes</h4>
          <p>Short public sessions for resetting midday tension. Choose gently padded seating; include a short journal segment at the end.</p>
          <div class="plan-meta">From $25</div>
          <a class="btn" href="events.html">See next dates</a>
        </article>
        <article class="plan-card">
          <h4>Deep Arc — 90 minutes</h4>
          <p>Longer sound immersion with breath-guided transitions and intention-setting prompts. Ideal for weekend recalibration.</p>
          <div class="plan-meta">From $55</div>
          <a class="btn" href="book.html">Reserve a spot</a>
        </article>
        <article class="plan-card">
          <h4>Private Resonance — 1:1 or small group</h4>
          <p>Personalized sessions for specific goals: sleep supports, performance focus, or emotional release.</p>
          <div class="plan-meta">Custom pricing</div>
          <a class="btn" href="private-sessions.html">Request details</a>
        </article>
      </div>
    </section>

    <section class="micro-habits" id="micro-habits">
      <h3>Micro practices you can do today</h3>
      <ul>
        <li><strong>Three slow exhales:</strong> Set a timer for 2 minutes, inhale 3s, hold 2s, exhale 6s, repeat 6 times.</li>
        <li><strong>Chair bell:</strong> Close your eyes for a minute when a bell rings — note tension and soften jaw.</li>
        <li><strong>One-line journal:</strong> Write one sentence: "I want today to feel like..."</li>
      </ul>
      <div class="micro-cta">
        <button class="btn" id="tryNowBtn2">Try a short practice</button>
      </div>
    </section>

    <section class="pricing" id="pricing">
      <h3>Rates & access</h3>
      <p class="muted">Transparent pricing framed around access and long-term consistency.</p>
      <div class="pricing-grid">
        <div class="tier">
          <h4>Drop-in</h4>
          <div class="price">$25</div>
          <p>Single session credit, ideal for new visitors.</p>
          <a class="btn" href="book.html">Book a drop-in</a>
        </div>
        <div class="tier featured">
          <h4>Series Pass</h4>
          <div class="price">$90 / 4</div>
          <p>Four sessions in a flexible plan — build a rhythm with preferential signup.</p>
          <a class="btn primary" href="pricing.html">Choose a pass</a>
        </div>
        <div class="tier">
          <h4>Private Package</h4>
          <div class="price">Custom</div>
          <p>Tailored sessions for individuals and small teams. Concierge booking.</p>
          <a class="btn" href="private-sessions.html">Inquire</a>
        </div>
      </div>
    </section>

    <section class="event-preview" id="event-preview">
      <h3>Next gathering — preview</h3>
      <div class="event-card">
        <div class="event-info">
          <div class="event-meta">Saturday • 7:00 PM</div>
          <h4 class="event-title">Evening Resonance Circle</h4>
          <p class="event-location">{{CITY}}, {{STATE}} • Cozy studio</p>
          <p class="event-desc">A guided soundscape to ease into restful clarity. Limited capacity to preserve intimacy.</p>
        </div>
        <div class="event-actions">
          <div class="seats">
            <label>Choose seats</label>
            <div class="seat-controls">
              <button id="decSeat" class="seat-btn">−</button>
              <input id="seatCount" type="text" value="1" readonly>
              <button id="incSeat" class="seat-btn">+</button>
            </div>
            <small id="seatsLeft">10 seats left</small>
          </div>
          <div class="pack">
            <label for="packStyle">What should I bring?</label>
            <select id="packStyle">
              <option value="basic">Basic comfort</option>
              <option value="deep">For deep sessions</option>
              <option value="travel">Travel-friendly</option>
            </select>
            <button id="makePack" class="btn">Generate pack list</button>
            <div id="packOutput" class="pack-output" aria-live="polite"></div>
          </div>
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>
    </section>

    <section class="final-cta" id="final-cta">
      <h3>Ready to shift your rhythm?</h3>
      <p>Reserve a seat or inquire about a private series. We keep groups intentionally small to preserve quality.</p>
      <div class="final-actions">
        <a class="btn primary" href="book.html">Reserve now</a>
        <a class="btn" href="contact.html">Ask a question</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div>
      <p>Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      <p>Serving {{CITY}}, {{STATE}}.</p>
    </div>
    <small>All content is informational and not medical advice. See contraindications above.</small>
  </footer>

  <!-- Guided exercise modal -->
  <div id="exerciseModal" class="modal" aria-hidden="true">
    <div class="modal-content" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
      <button class="modal-close" id="closeModal">✕</button>
      <h4 id="modalTitle">Short Guided Practice</h4>
      <div id="exerciseArea">
        <div id="breathStage" class="stage">
          <h5>Breathe — follow the circle</h5>
          <div class="breath-circle" id="breathCircle" aria-hidden></div>
          <p id="breathHint">Inhale 4 — Hold 2 — Exhale 6</p>
        </div>
        <div id="journalStage" class="stage hidden">
          <h5>Journaling prompt</h5>
          <p class="prompt">Write one line: "I want this hour to give me..."</p>
          <textarea id="journalInput" rows="4" placeholder="One honest line..."></textarea>
          <button class="btn" id="saveNote">Save line</button>
        </div>
        <div id="intentionStage" class="stage hidden">
          <h5>Set an intention</h5>
          <input id="intentionInput" type="text" placeholder="A brief intention (e.g. softened shoulders)" />
          <div class="intent-actions">
            <button class="btn primary" id="finishPractice">Finish</button>
            <button class="btn" id="restartPractice">Restart</button>
          </div>
        </div>
        <div class="exercise-controls">
          <button class="btn" id="prevStage" disabled>Back</button>
          <button class="btn primary" id="nextStage">Start</button>
        </div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
