{"path":"assets/css/styles.css","content":"/* Base styles for calm, editorial sound bath site */
:root{
  --bg:#fbfbfb;
  --muted:#6b6b6b;
  --accent:#2b5a7a;
  --accent-2:#8ab0b8;
  --card:#ffffff;
  --radius:10px;
  --max-width:1100px;
  font-synthesis: none;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:var(--bg); color:#0b0b0b; -webkit-font-smoothing:antialiased}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:22px;max-width:var(--max-width);margin:0 auto}
.brand .logo{margin:0;font-size:18px;letter-spacing:0.6px}
.brand .tag{margin:0;color:var(--muted);font-size:13px}
.main-nav a{margin-left:14px;color:var(--muted);text-decoration:none}
.main-nav .cta-link{background:transparent;border:1px solid var(--accent);padding:8px 12px;border-radius:8px;color:var(--accent)}
.hero{position:relative;padding:48px 22px;background:linear-gradient(180deg,#fff 0%,#f7fcfd 100%);overflow:hidden}
.hero-pattern{position:absolute;left:0;top:0;width:100%;height:100%;opacity:0.25}
.hero-inner{position:relative;max-width:var(--max-width);margin:0 auto;text-align:left}
.hero h2{font-size:28px;margin:8px 0}
.lead{color:var(--muted);margin:8px 0 16px}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;background:transparent;border:1px solid #ddd;color:#111;text-decoration:none;cursor:pointer}
.btn.primary{background:var(--accent);color:#fff;border-color:transparent}
.btn.ghost{background:transparent;border:1px solid transparent;color:var(--accent)}
.diagnostic, .plan, .micro-habits, .pricing, .event-preview, .final-cta{max-width:var(--max-width);margin:28px auto;padding:18px}
.diagnostic p.small{font-size:13px;color:var(--muted)}
.plans-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:12px}
.plan-card{background:var(--card);padding:14px;border-radius:var(--radius);box-shadow:0 6px 18px rgba(8,10,12,0.04)}
.plan-meta{color:var(--accent);font-weight:600;margin-top:8px}
.micro-habits ul{padding-left:18px}
.pricing-grid{display:flex;gap:12px;flex-wrap:wrap}
.tier{flex:1;min-width:160px;background:var(--card);padding:14px;border-radius:10px}
.tier.featured{border:2px solid var(--accent-2)}
.event-card{display:flex;gap:18px;background:linear-gradient(180deg,#fff,#fcfeff);padding:16px;border-radius:12px;align-items:flex-start}
.event-info{flex:1}
.event-actions{width:320px}
.seat-controls{display:flex;align-items:center;gap:8px;margin-top:8px}
.seat-btn{padding:8px 10px;border-radius:8px;border:1px solid #ddd;background:#fff}
#seatCount{width:36px;text-align:center;border:1px solid #eee;padding:6px;border-radius:6px;background:#fafafa}
.pack-output{margin-top:10px;padding:10px;background:#fff;border-radius:8px;border:1px dashed #e6f2f5;color:var(--muted)}
.site-footer{padding:22px;text-align:center;color:var(--muted);font-size:13px}
/* Modal */
.modal{position:fixed;inset:0;background:rgba(8,10,12,0.45);display:flex;align-items:center;justify-content:center;opacity:0;pointer-events:none;transition:opacity .18s ease}
.modal[aria-hidden="false"]{opacity:1;pointer-events:auto}
.modal-content{background:#fff;padding:18px;border-radius:12px;max-width:560px;width:92%;position:relative}
.modal-close{position:absolute;right:10px;top:10px;border:none;background:transparent;font-size:18px;cursor:pointer}
.stage{margin-top:12px}
.hidden{display:none}
.breath-circle{width:140px;height:140px;border-radius:50%;margin:12px auto;background:radial-gradient(circle at 30% 30%, rgba(43,90,122,0.12), rgba(138,176,184,0.06));display:flex;align-items:center;justify-content:center;transition:transform 1s ease}
.prompt{color:var(--muted)}
textarea,input[type="text"]{width:100%;padding:10px;border-radius:8px;border:1px solid #eee;margin-top:8px}
.intent-actions{display:flex;gap:8px;margin-top:8px}
.exercise-controls{display:flex;justify-content:space-between;gap:10px;margin-top:12px}
@media(max-width:720px){.event-card{flex-direction:column}.main-nav{display:none}}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Seat selector (local fake) and packing list generator
  var seatsLeft = 10;
  var seatCountEl = document.getElementById('seatCount');
  var inc = document.getElementById('incSeat');
  var dec = document.getElementById('decSeat');
  var seatsLeftEl = document.getElementById('seatsLeft');
  var packSelect = document.getElementById('packStyle');
  var makePackBtn = document.getElementById('makePack');
  var packOutput = document.getElementById('packOutput');

  function updateSeatsDisplay(){
    seatCountEl.value = Math.max(1, Math.min(6, Number(seatCountEl.value)));
    seatsLeftEl.textContent = (seatsLeft - Number(seatCountEl.value)) + ' seats left';
  }

  inc.addEventListener('click', function(){
    var n = Number(seatCountEl.value) + 1;
    if(n > 6) n = 6;
    if(n > seatsLeft) n = seatsLeft;
    seatCountEl.value = n;
    updateSeatsDisplay();
  });
  dec.addEventListener('click', function(){
    var n = Number(seatCountEl.value) - 1;
    if(n < 1) n = 1;
    seatCountEl.value = n;
    updateSeatsDisplay();
  });

  // Packing list generator
  var presets = {
    basic: ['Yoga mat or blanket','Travel pillow/neck roll','Water bottle','Comfortable clothes','Socks or slippers'],
    deep: ['Thick mat/bolster','Eye mask or scarf','Ear cover if needed','Notebook + pen','Extra blanket'],
    travel: ['Foldable mat','Small travel pillow','Earbuds for transit','Compact journal','Light scarf']
  };

  makePackBtn.addEventListener('click', function(){
    var style = packSelect.value;
    var items = presets[style] || presets.basic;
    packOutput.textContent = 'Suggested kit: ' + items.join(', ') + '.';
    // friendly tip
    var tip = '\nArrive 10–15 minutes early to settle and lay out your space.';
    packOutput.textContent += ' ' + tip;
  });

  updateSeatsDisplay();

  // Guided exercise modal
  var modal = document.getElementById('exerciseModal');
  var tryButtons = document.querySelectorAll('#tryNowBtn, #tryNowBtn2');
  var closeModal = document.getElementById('closeModal');
  var next = document.getElementById('nextStage');
  var prev = document.getElementById('prevStage');
  var stages = ['breathStage','journalStage','intentionStage'];
  var cur = 0;
  var breathCircle = document.getElementById('breathCircle');
  var breathHint = document.getElementById('breathHint');
  var journalStage = document.getElementById('journalStage');
  var journalInput = document.getElementById('journalInput');
  var saveNote = document.getElementById('saveNote');
  var intentionInput = document.getElementById('intentionInput');
  var finish = document.getElementById('finishPractice');
  var restart = document.getElementById('restartPractice');

  function showModal(){
    modal.setAttribute('aria-hidden','false');
    document.body.style.overflow = 'hidden';
    cur = 0; renderStage();
  }
  function hideModal(){
    modal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
  }

  tryButtons.forEach(function(b){b.addEventListener('click', showModal)});
  closeModal.addEventListener('click', hideModal);

  function renderStage(){
    stages.forEach(function(id,i){
      var el = document.getElementById(id);
      if(!el) return;
      if(i === cur) el.classList.remove('hidden'); else el.classList.add('hidden');
    });
    prev.disabled = (cur === 0);
    next.textContent = (cur === stages.length -1) ? 'Next' : (cur === 0 ? 'Start' : 'Continue');
    // breathing visual kicks when on first stage
    if(cur === 0){ startBreathCycle(); } else { stopBreathCycle(); }
  }

  prev.addEventListener('click', function(){ if(cur>0){cur--; renderStage();} });
  next.addEventListener('click', function(){
    if(cur < stages.length -1){ cur++; renderStage(); } else { // move forward behavior
      // if at final stage, advance to intention and close
      finish.focus();
    }
  });

  // simple breath animation: scale circle over timed loop (4-2-6 seconds pattern)
  var breathTimer = null;
  function startBreathCycle(){
    var phase = 0; // 0 inhale,1 hold,2 exhale
    var cycle = function(){
      if(phase===0){ // inhale 4
        breathCircle.style.transform = 'scale(1.18)';
        breathHint.textContent = 'Inhale 4 — Hold 2 — Exhale 6';
        phase = 1; breathTimer = setTimeout(cycle,4000);
      } else if(phase===1){ // hold 2
        breathCircle.style.transform = 'scale(1.18)';
        phase = 2; breathTimer = setTimeout(cycle,2000);
      } else { // exhale 6
        breathCircle.style.transform = 'scale(0.82)';
        phase = 0; breathTimer = setTimeout(cycle,6000);
      }
    };
    cycle();
  }
  function stopBreathCycle(){ if(breathTimer) { clearTimeout(breathTimer); breathTimer = null; breathCircle.style.transform = 'scale(1)'; } }

  // journaling save
  saveNote.addEventListener('click', function(){
    var v = journalInput.value.trim();
    if(!v){ alert('Write a short line — keep it simple.'); return; }
    journalInput.value = '';
    alert('Saved: "' + v + '". It will help anchor your practice.');
  });

  finish.addEventListener('click', function(){
    var intent = intentionInput.value.trim();
    if(!intent) intent = 'Presence';
    alert('Intention set: ' + intent + '. You can revisit this before or after a session.');
    hideModal();
  });
  restart.addEventListener('click', function(){ cur = 0; renderStage(); });

  // keyboard escape closes modal
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape' && modal.getAttribute('aria-hidden') === 'false') hideModal(); });

  // safety: focus trap simple implementation (keeps focus inside modal when open)
  document.addEventListener('focusin', function(e){ if(modal.getAttribute('aria-hidden') === 'false' && !modal.contains(e.target)){ e.stopPropagation(); modal.querySelector('.modal-close').focus(); } });

})();"} 
